/**
 * The core data model for the Shango Conversation.
 * The Conversation is a living document composed of immutable, typed blocks.
 */

import { generateId } from "./store"

// The distinct types of content that can exist in a Conversation.
export type BlockType =
  | "idea"
  | "dialogue.user"
  | "dialogue.shango"
  | "understanding"
  | "plan"
  | "architecture"
  | "tasks"
  | "execution"
  | "result"
  | "decision"
  | "error"

// The base interface that all blocks adhere to.
export interface BaseBlock {
  id: string
  type: BlockType
  // Every block is created at a specific moment in time.
  createdAt: string
}

// The initial spark from the builder.
export interface IdeaBlock extends BaseBlock {
  type: "idea"
  content: string
}

// A user's response to a question from Shango.
export interface UserDialogueBlock extends BaseBlock {
  type: "dialogue.user"
  content: string
}

// A question or statement from Shango to the builder.
export interface ShangoDialogueBlock extends BaseBlock {
  type: "dialogue.shango"
  content: string
  // Optional flag for when Shango is awaiting a response.
  pending?: boolean
}

// A summary of Shango's understanding of the product.
export interface UnderstandingBlock extends BaseBlock {
  type: "understanding"
  summary: string
  // The builder must confirm this before the lifecycle progresses.
  isConfirmed: boolean
}

// The collection of all valid block types.
export type ConversationBlock =
  | IdeaBlock
  | UserDialogueBlock
  | ShangoDialogueBlock
  | UnderstandingBlock

// ─── Factory Functions ────────────────────────────────────────────────────────

/**
 * Creates a new IdeaBlock.
 */
export function createIdeaBlock(content: string): IdeaBlock {
  return {
    id: generateId(),
    type: "idea",
    content,
    createdAt: new Date().toISOString(),
  }
}

/**
 * Creates a new UserDialogueBlock.
 */
export function createUserDialogueBlock(content:string): UserDialogueBlock {
  return {
    id: generateId(),
    type: "dialogue.user",
    content,
    createdAt: new Date().toISOString(),
  }
}

