    if (!id || projectLoadTried) {
      navigate("/projects")
      return
    }
  }, [project?.id, id, isProjectLoading, projectLoadTried, navigate])

  // Build trigger — watches version count
  useEffect(() => {
    if (!project) return
    if (project.versions.length > prevVersionCount.current) {
      prevVersionCount.current = project.versions.length
      setIsRebuilding(true)
      setBuildSuccess(false)
      setConsoleOpen(true)
      if (consoleLogs.length === 0) {
        setConsoleLogs([])
        const logs = buildConsoleLogs(project.name)
        logs.forEach((log, i) => {
          setTimeout(() => setConsoleLogs((prev) => [...prev, log]), i * 160)
        })
      }
      const t = setTimeout(() => {
        setIsRebuilding(false)
        setPreviewKey((k) => k + 1)
        setBuildSuccess(true)
        setTimeout(() => setBuildSuccess(false), 2000)
      }, 1100)
      return () => clearTimeout(t)
    }
  }, [project?.versions.length])

  // Global keyboard shortcuts
  useEffect(() => {
    const handler = (e: globalThis.KeyboardEvent) => {
      const mod = e.metaKey || e.ctrlKey
      if (mod && e.key === "p") {
        e.preventDefault()
        setConversationCollapsed((v) => !v)
      }
      if (mod && e.key === "y") {
        e.preventDefault()
        setHistoryOpen((v) => !v)
      }
      if (mod && e.key === "d") {
        e.preventDefault()
        setDeployOpen(true)
      }
      if (mod && e.key === "s") {
        e.preventDefault()
        setShareOpen(true)
      }
      if (mod && e.key === "h") {
        e.preventDefault()
        navigate("/")
      }
      if (mod && e.key === "n") {
        e.preventDefault()
        navigate("/?new=1")
      }
      if (mod && e.key === "e") {
        e.preventDefault()
        setCodeView((v) => !v)
      }
      if (mod && e.key === ",") {
        e.preventDefault()
        setProjectSettingsOpen(true)
      }
      if (mod && e.key === "1") {
        e.preventDefault()
        setViewport("desktop")
      }
      if (mod && e.key === "2") {
        e.preventDefault()
        setViewport("tablet")
      }
      if (mod && e.key === "3") {
        e.preventDefault()
        setViewport("mobile")
      }
      if (e.key === "Escape") {
        setFullscreen(false)
      }
      if (mod && e.key === "r") {
        e.preventDefault()
        if (!isGenerating) {
          const lastUserMsg = [...localMessages]
            .reverse()
            .find((m) => m.role === "user")
          if (lastUserMsg) {
            setIsGenerating(true)
            if (aiTimerRef.current) clearTimeout(aiTimerRef.current)
            aiTimerRef.current = setTimeout(() => {
              void handleGenerationResponse(lastUserMsg.content, {
                addVersion: false,
              })
            }, 0)
          }
        }
      }
    }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [isGenerating, localMessages])

  // Resize handle
  const handleMouseDown = (e: ReactMouseEvent) => {
    setIsDragging(true)
    dragStartX.current = e.clientX
    dragStartWidth.current = panelWidth
  }

  useEffect(() => {
    if (!isDragging) return
    const handleMove = (e: MouseEvent) => {
      const delta = e.clientX - dragStartX.current
      setPanelWidth(
        Math.max(240, Math.min(560, dragStartWidth.current + delta)),
      )
    }
    const handleUp = () => setIsDragging(false)
    window.addEventListener("mousemove", handleMove)
    window.addEventListener("mouseup", handleUp)
    return () => {
      window.removeEventListener("mousemove", handleMove)
      window.removeEventListener("mouseup", handleUp)
    }
  }, [isDragging])

  // Send handler: only append the user message. Version creation happens after successful generation.
  const handleSend = (msg: string) => {
    const currentProject = projectRef.current
    if (!currentProject || !id) return
    const now = new Date().toISOString()
    const userMessage: ChatMessage = {
      id: generateId(),
      role: "user",
      content: msg,
      timestamp: now,
    }
    // Stamp generatingAt so mergePersistedProjects protects this project from
    // remote overwrites while generation is in flight.
    const updatedProject = appendChatMessageToProject(
      { ...currentProject, generatingAt: now },
      userMessage,
      now,
    )
    projectRef.current = updatedProject
    setProjects((prev) => prev.map((p) => (p.id === id ? updatedProject : p)))
    setActiveProject(id)
    void syncProjectToBackend(updatedProject)
  }

  const handleGenerationResponse = async (
    prompt: string,
    options: { addVersion: boolean },
  ) => {
    const currentProject = projectRef.current
    if (!currentProject || !id) return

    const pendingAssistantId = generateId()
    const controller = new AbortController()
    abortControllerRef.current = controller

    const appendConsoleEntry = (
      message: string,
      level: ConsoleEntry["level"] = "info",
    ) => {
      const ts = new Date().toLocaleTimeString("en-US", {
        hour12: false,
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      })
      setConsoleLogs((prev) => [...prev, { ts, level, msg: message }])
      setConsoleOpen(true)
    }

    const upsertStreamedFile = (file: StreamedFileSnapshot) => {
      setStreamedFiles((prev) => {
        const existingIndex = prev.findIndex(
          (entry) => entry.path === file.path,
        )
        if (existingIndex >= 0) {
          const next = [...prev]
          next[existingIndex] = { ...next[existingIndex], ...file }
          return next
        }
        return [...prev, file]
      })
    }

    setStreamedFiles([])

    setLocalMessages((prev) => [
      ...prev,
      {
        id: pendingAssistantId,
        role: "assistant",
        content: "",
        timestamp: "Just now",
        pending: true,
      },
    ])

    try {
      const currentVersionPrompt =
        currentProject.versions.find((v) => v.isCurrent)?.prompt ??
        currentProject.initialPrompt
      const { mode, model, language } = resolveGenerationPreferences()
      const result = await generateProjectResponse(prompt, {
        previousArtifact: currentProject.artifact,
        previousPrompt: currentVersionPrompt,
        mode,
        model,
        language,
        projectId: currentProject.id,
        activeFile,
        enabledSkills: enabledSkills.flatMap((id) => {
          const skill = ALL_SKILLS.find((candidate) => candidate.id === id)
          return skill
            ? [{ id: skill.id, name: skill.name, purpose: skill.purpose }]
            : []
        }),
        workspaceFiles: (currentProject.files ?? []).map((file) => ({
          path: file.path,
          content: file.content,
          language: file.language,
        })),
        signal: controller.signal,
        onEvent: (event) => {
          if (event.type === "delta" && typeof event.content === "string") {
            // Let the builder see concise progress arrive while the workspace is assembled.
            setLocalMessages((prev) =>
              prev.map((message) =>
                message.id === pendingAssistantId
                  ? {
                      ...message,
                      content: `${message.content}${event.content}`.slice(
                        0,
                        900,
                      ),
                    }
                  : message,
              ),
            )
            // Update shared status: assistant is composing
            setActivityStatus({ status: "assistant_composing" })
          }
          if (event.type === "console" && typeof event.message === "string") {
            appendConsoleEntry(event.message, "info")
          }
          if (
            event.type === "file" &&
            event.file &&
            typeof event.file === "object"
          ) {
            const filePayload = event.file as {
              path?: string
              operation?: string
              language?: string
              content?: string
            }
            if (filePayload.path) {
              appendConsoleEntry(
                `Updated ${filePayload.path}${
                  filePayload.operation ? ` (${filePayload.operation})` : ""
                }`,
                "success",
              )
              setActiveFile(filePayload.path)
              // File events are concrete evidence that workspace changes are being applied.
              // Update shared status with file count.
              setActivityStatus({
                status: "applying_workspace_changes",
                details: { filesChanged: (streamedFiles.length || 0) + 1 },
              })
              if (typeof filePayload.content === "string") {
                upsertStreamedFile({
                  path: filePayload.path,
                  content: filePayload.content,
                  language: filePayload.language,
                })
              } else {
                upsertStreamedFile({
                  path: filePayload.path,
                  language: filePayload.language,
                })
              }
            }
          }
          if (
            event.type === "version" &&
            event.version &&
            typeof event.version === "object"
          ) {
            const versionPayload = event.version as {
              label?: string
              prompt?: string
            }
            if (versionPayload.label) {
              appendConsoleEntry(
                `Version checkpoint: ${versionPayload.label}`,
                "success",
              )
            }
          }
        },
      })
      const now = new Date().toISOString()
      const sensitiveChanges = findSensitiveWorkspaceChanges(
        currentProject.files,
        result.fileChanges,
      )
      if (sensitiveChanges.length > 0) {
        setPendingGenerationReview({
          project: currentProject,
          prompt,
          result,
          completedAt: now,
          addVersion: options.addVersion,
          mode,
          pendingAssistantId,
        })
        setLocalMessages((prev) =>
          prev.map((msg) =>
            msg.id === pendingAssistantId
              ? {
                  ...msg,
                  content:
                    "This direction touches protected workspace work. Review the change before it is applied.",
                  pending: false,
                  timestamp: "Just now",
                }
              : msg,
          ),
        )
        addToast("Review required before protected work is changed", "default")
        return
      }

      commitGeneration({
        project: currentProject,
        prompt,
        result,
        completedAt: now,
        addVersion: options.addVersion,
        mode,
        pendingAssistantId,
      })
    } catch (error) {
      if (controller.signal.aborted) {
        setLocalMessages((prev) =>
          prev.map((msg) =>
            msg.id === pendingAssistantId
              ? {
                  ...msg,
                  content: msg.content || "Generation stopped.",
                  pending: false,
                }
              : msg,
          ),
        )
        addToast("Stopped", "default")
        return
      }
      const message =
        error instanceof Error ? error.message : "Generation failed"
      setActivityStatus({ status: "generation_failed" })
      setLocalMessages((prev) =>
        prev.map((msg) =>
          msg.id === pendingAssistantId
            ? {
                ...msg,
                content:
                  "The generation request could not be completed. Please try again.",
                pending: false,
              }
            : msg,
        ),
      )
      // Persist a recoverable failure state so a refresh does not lose the retry context.
      const failedAssistantMessage: ChatMessage = {
        id: generateId(),
        role: "assistant",
        content:
          "The generation request could not be completed. You can retry the same instruction.",
        timestamp: new Date().toISOString(),
      }
      const failedProject = appendChatMessageToProject(
        { ...currentProject, generatingAt: undefined },
        failedAssistantMessage,
        failedAssistantMessage.timestamp,
      )
      projectRef.current = failedProject
      setProjects((prev) => prev.map((p) => (p.id === id ? failedProject : p)))
      void syncProjectToBackend(failedProject)
      setRetryPrompt(prompt)
      addToast(message, "error")
    } finally {
      setIsGenerating(false)
      if (abortControllerRef.current === controller) {
        abortControllerRef.current = null
      }
    }
  }

  const startWorkspaceGeneration = (
    prompt: string,
    options: { appendUserMessage?: boolean } = {},
  ) => {
    if (!prompt || isGenerating || !project) return
    const appendUserMessage = options.appendUserMessage ?? true
    const selectedModel = (() => {
      try {
        return (
          JSON.parse(localStorage.getItem("shango_settings") ?? "{}").model ??
          "balanced"
        )
      } catch {
        return "balanced"
      }
    })()
    setInput("")
    setRetryPrompt(null)
    setActivityStatus({ status: "request_sent" })
    setIsGenerating(true)
    if (appendUserMessage) {
      setLocalMessages((prev) => [
        ...prev,
        {
          id: generateId(),
          role: "user" as const,
          content: prompt,
          timestamp: "Just now",
        },
      ])
      handleSend(prompt)
    } else {
      const retryProject = {
        ...projectRef.current!,
        generatingAt: new Date().toISOString(),
      }
      projectRef.current = retryProject
      setProjects((prev) => prev.map((p) => (p.id === id ? retryProject : p)))
      void syncProjectToBackend(retryProject)
    }
    if (aiTimerRef.current) clearTimeout(aiTimerRef.current)
    void handleGenerationResponse(prompt, { addVersion: true })
    addToast(`Sending to ${selectedModel} model`, "default")
  }

  const commitGeneration = (review: PendingGenerationReview) => {
    const nextProject = applyGenerationResultToProject(
      review.project,
      review.prompt,
      review.result,
      review.completedAt,
      { addVersion: review.addVersion, mode: review.mode },
    )
    if (nextProject) {
      const clearedProject = { ...nextProject, generatingAt: undefined }
      projectRef.current = clearedProject
      setProjects((prev) => prev.map((p) => (p.id === id ? clearedProject : p)))
      void syncProjectToBackend(clearedProject)
      // Commit implies workspace files have been applied
      setActivityStatus({
        status: "workspace_updated",
        details: {
          filesChanged: review.result.fileChanges?.length ?? undefined,
        },
      })
      // After brief moment signal ready for refinement
      setTimeout(
        () => setActivityStatus({ status: "ready_for_refinement" }),
        600,
      )
    }
    setRetryPrompt(null)
    setLocalMessages((prev) =>
      prev.map((msg) =>
        msg.id === review.pendingAssistantId
          ? {
              ...msg,
              content: review.result.assistant || msg.content,
              pending: false,
              timestamp: "Just now",
            }
          : msg,
      ),
    )
    setPendingGenerationReview(null)
    addToast(
      review.mode === "plan"
        ? "Plan ready"
        : review.addVersion
          ? "Version saved"
          : "Regenerated",
      review.result.usedFallback ? "default" : "success",
    )
  }

  const dismissGenerationReview = () => {
    const review = pendingGenerationReview
    if (!review) return
    const clearedProject = { ...review.project, generatingAt: undefined }
    projectRef.current = clearedProject
    setProjects((prev) => prev.map((p) => (p.id === id ? clearedProject : p)))
    void syncProjectToBackend(clearedProject)
    setLocalMessages((prev) =>
      prev.map((msg) =>
        msg.id === review.pendingAssistantId
          ? {
              ...msg,
              content:
                "No files were changed. The proposed removal was not applied.",
              pending: false,
              timestamp: "Just now",
            }
          : msg,
      ),
    )
    setPendingGenerationReview(null)
    addToast("Change review dismissed", "default")
    setActivityStatus({ status: "awaiting_direction" })
  }

  const handleWorkspaceSend = () => {
    startWorkspaceGeneration(input.trim())
  }

  const retryFailedGeneration = () => {
    if (!retryPrompt) return
    startWorkspaceGeneration(retryPrompt, { appendUserMessage: false })
  }

  const stopGeneration = () => {
    if (aiTimerRef.current) clearTimeout(aiTimerRef.current)
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
      abortControllerRef.current = null
    }
    setIsGenerating(false)
    setLocalMessages((prev) =>
      prev.map((msg) =>
        msg.pending
          ? {
              ...msg,
              content: msg.content || "Generation stopped.",
              pending: false,
            }
          : msg,
      ),
    )
    addToast("Stopped", "default")
    setActivityStatus({ status: "generation_stopped" })
  }

  const handleForgeKeyDown = (e: ReactKeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault()
      handleWorkspaceSend()
    }
  }

  if (!project) return null

  const versionsCount = project.versions.length || 1
  const slug = project.name
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .slice(0, 28)
  const reviewChanges = pendingGenerationReview
    ? buildGenerationReview(
        pendingGenerationReview.project.files,
        pendingGenerationReview.result.fileChanges,
      )
    : []
  const { label: maturityLabel, status: maturityStatus } =
    getActiveMaturityLabel(
      project.messages || [],
      project.versions || [],
      isGenerating,
    )

  return (
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "#080809",
        fontFamily: "var(--font-geist)",
      }}
    >
      <ProjectMemoryScreen project={project} />
      {/* Top status line: shared single-line activity status for the builder */}
      <div style={{ position: "relative", zIndex: 6 }}>
        {/* Render shared activity status in the page header area */}
        <ActivityStatusLine activityStatus={activityStatus} />
      </div>

      {/* ── Modals (escape canvas stacking context) ── */}
      <ShareModal
        open={shareOpen}
        onClose={() => setShareOpen(false)}
        projectName={project.name}
        projectId={project.id}
      />
      <DeployModal
        open={deployOpen}
        onClose={() => setDeployOpen(false)}
        projectName={project.name}
        projectId={project.id}
        currentVersion={versionsCount}
      />
      <ExportModal
        open={exportOpen}
        onClose={() => setExportOpen(false)}
        projectName={project.name}
      />
      <ConfirmationModal
        open={Boolean(pendingGenerationReview)}
        onClose={dismissGenerationReview}
        onConfirm={() => {
          if (pendingGenerationReview) commitGeneration(pendingGenerationReview)
        }}
        title="Review protected changes"
        message={(() => {
          const sensitive = pendingGenerationReview
            ? findSensitiveWorkspaceChanges(
                pendingGenerationReview.project.files,
                pendingGenerationReview.result.fileChanges,
              )
            : []
          const names = sensitive
            .slice(0, 3)
            .map((change) => change.path)
            .join(", ")
          const remainder =
            sensitive.length > 3 ? ` and ${sensitive.length - 3} more` : ""
          return `Shango prepared ${sensitive.length} protected change${
            sensitive.length === 1 ? "" : "s"
          }: ${names}${remainder}. Your workspace will not change until you approve this review.`
        })()}
        confirmLabel="Apply changes"
        destructive
        details={
          reviewChanges.length > 0 ? (
            <div
              style={{
                marginBottom: 20,
                maxHeight: 190,
                overflowY: "auto",
                border: "1px solid rgba(255,255,255,0.08)",
                borderRadius: 7,
              }}
            >
              {reviewChanges.map((change) => (
                <div
                  key={`${change.operation}:${change.path}`}
                  style={{
                    padding: "8px 10px",
                    borderBottom: "1px solid rgba(255,255,255,0.06)",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      gap: 7,
                      alignItems: "center",
                      fontFamily: "var(--font-mono-jetbrains)",
                      fontSize: 9.5,
                    }}
                  >
                    <span
                      style={{
                        color:
                          change.operation === "delete"
                            ? "#fca5a5"
                            : change.operation === "create"
                              ? "#86efac"
                              : "#fcd34d",
                        textTransform: "uppercase",
                      }}
                    >
                      {change.operation}
                    </span>
                    <span
                      style={{
                        color: "rgba(255,255,255,0.65)",
                        overflow: "hidden",
                        textOverflow: "ellipsis",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {change.path}
                    </span>
                  </div>
                  {change.removedPreview.map((line, index) => (
                    <div
                      key={`remove-${index}`}
                      style={{
                        marginTop: 4,
                        color: "rgba(252,165,165,0.75)",
                        fontFamily: "var(--font-mono-jetbrains)",
                        fontSize: 9,
                        whiteSpace: "pre-wrap",
                      }}
                    >
                      − {line}
                    </div>
                  ))}
                  {change.addedPreview.map((line, index) => (
                    <div
                      key={`add-${index}`}
                      style={{
                        marginTop: 3,
                        color: "rgba(134,239,172,0.75)",
                        fontFamily: "var(--font-mono-jetbrains)",
                        fontSize: 9,
                        whiteSpace: "pre-wrap",
                      }}
                    >
                      + {line}
                    </div>
                  ))}
                  {(change.removedDetails.length > 0 ||
                    change.addedDetails.length > 0 ||
                    change.removedHiddenCount > 0 ||
                    change.addedHiddenCount > 0) && (
                    <details style={{ marginTop: 7 }}>
                      <summary
                        style={{
                          cursor: "pointer",
                          color: "rgba(255,255,255,0.5)",
                          fontFamily: "var(--font-geist)",
                          fontSize: 9,
                        }}
                      >
                        Show more changed lines
                      </summary>
                      {change.removedDetails.map((line, index) => (
                        <div
                          key={`remove-detail-${index}`}
                          style={{
                            marginTop: 4,
                            color: "rgba(252,165,165,0.75)",
                            fontFamily: "var(--font-mono-jetbrains)",
                            fontSize: 9,
                            whiteSpace: "pre-wrap",
                          }}
                        >
                          − {line}
                        </div>
                      ))}
                      {change.addedDetails.map((line, index) => (
                        <div
                          key={`add-detail-${index}`}
                          style={{
                            marginTop: 3,
                            color: "rgba(134,239,172,0.75)",
                            fontFamily: "var(--font-mono-jetbrains)",
                            fontSize: 9,
                            whiteSpace: "pre-wrap",
                          }}
                        >
                          + {line}
                        </div>
                      ))}
                      {(change.removedHiddenCount > 0 ||
                        change.addedHiddenCount > 0) && (
                        <div
                          style={{
                            marginTop: 5,
                            color: "rgba(255,255,255,0.35)",
                            fontFamily: "var(--font-geist)",
                            fontSize: 9,
                          }}
                        >
                          Large change:{" "}
                          {change.removedHiddenCount + change.addedHiddenCount}{" "}
                          additional lines are not shown.
                        </div>
                      )}
                    </details>
                  )}
                </div>
              ))}
            </div>
          ) : undefined
        }
      />
      <ConnectorsDrawer
        open={connectorsOpen}
        onClose={() => setConnectorsOpen(false)}
      />
      <ZenCommandPalette
        isOpen={zenPaletteOpen}
        onClose={() => setZenPaletteOpen(false)}
        onSubmit={(prompt) => {
          setInput(prompt)
          // We need to defer handleWorkspaceSend slightly so state can settle
          setTimeout(() => {
            if (textareaRef.current) {
              textareaRef.current.value = prompt
              textareaRef.current.dispatchEvent(
                new Event("change", { bubbles: true }),
              )
              const sendBtn = document.getElementById("shango-send-btn")
              sendBtn?.click()
            }
          }, 50)
        }}
        isGenerating={isGenerating}
      />

      {/* ── Master canvas ── */}
      <div
        style={{
          position: "absolute",
          inset: 10,
          borderRadius: 18,
          border: "1px solid rgba(255,255,255,0.055)",
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          background: "#0a0a0b",
          cursor: isDragging ? "col-resize" : "default",
          userSelect: isDragging ? "none" : "auto",
          boxShadow: "0 0 0 1px rgba(0,0,0,0.8), 0 24px 80px rgba(0,0,0,0.6)",
        }}
      >
        {/* ══ SINGLE MASTER HEADER — 48px, full canvas width ══════════════════ */}
        <header
          style={{
            height: 48,
            flexShrink: 0,
            display: "flex",
            alignItems: "center",
            padding: "0 10px",
            gap: 0,
            background: "rgba(14,14,16,0.98)",
            borderBottom: "1px solid rgba(255,255,255,0.05)",
            zIndex: 20,
            opacity: 1,
            pointerEvents: "auto",
            transition: "opacity 0.2s ease",
          }}
        >
          {/* ── LEFT — Profile + project context ── */}
          <div
            style={{
              width: conversationCollapsed
                ? "auto"
                : Math.max(180, panelWidth - 10),
              display: "flex",
              alignItems: "center",
              justifyContent: conversationCollapsed
                ? "flex-start"
                : "space-between",
              gap: 4,
              flexShrink: 0,
              paddingRight: conversationCollapsed ? 0 : 4,
              boxSizing: "border-box",
              transition: isDragging
                ? "none"
                : "width 0.32s cubic-bezier(0.16,1,0.3,1)",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 2,
                minWidth: 0,
              }}
            >
              {/* Profile avatar */}
              <div style={{ position: "relative", marginRight: 2 }}>
                <button
                  onClick={() => setProfileOpen((v) => !v)}
